-- public.rank_name_refusal(p_world uuid, p_founder uuid, p_name text, p_except bigint)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.rank_name_refusal(p_world uuid, p_founder uuid, p_name text, p_except bigint DEFAULT NULL::bigint)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select case
    when btrim(coalesce(p_name, '')) = '' then 'Name the rank.'
    when length(btrim(p_name)) > rank_name_max() then 'Rank name: max ' || rank_name_max() || ' characters.'
    when lower(btrim(p_name)) = 'founder' then 'Founder is not a rank name.'
    when private.name_refusal(p_world, p_founder, p_name) is not null then private.name_refusal(p_world, p_founder, p_name)
    when exists (select 1 from deed_rank_def r where r.world_id = p_world and r.founder = p_founder
                   and r.id is distinct from p_except and lower(r.name) = lower(btrim(p_name)))
      then (select d.name from deed d where d.world_id = p_world and d.founded_by = p_founder)
           || ' already has a rank named ' || btrim(p_name) || '.'
  end
$function$
